// ============================================================
// PURE MATH NODE — 14 DAYS, SPLIT INTO THIS WEEK & LAST WEEK
// ============================================================
const items = $input.all();
const now = new Date();

// Week boundaries
const thisWeekStart = new Date();
thisWeekStart.setDate(now.getDate() - 7);

const lastWeekStart = new Date();
lastWeekStart.setDate(now.getDate() - 14);

const lastWeekEnd = new Date(thisWeekStart);

// Date normalizer
const normalizeDate = (raw) => {
  const parts = String(raw).split('-');
  return new Date(`${parts[0]}-${String(parts[1]).padStart(2,'0')}-${String(parts[2]).padStart(2,'0')}`);
};

// Split into two buckets
const thisWeekRows = [];
const lastWeekRows = [];

for (const item of items) {
  const rowDate = normalizeDate(item.json['DATE']);
  if (rowDate >= thisWeekStart && rowDate <= now) {
    thisWeekRows.push(item);
  } else if (rowDate >= lastWeekStart && rowDate < lastWeekEnd) {
    lastWeekRows.push(item);
  }
}

// Calculator function
const calcMetrics = (rows) => {
  let totalRevenue = 0;
  let totalSpend = 0;
  const entries = [];

  for (const row of rows) {
    const rev = parseFloat(row.json['REVENUE']) || 0;
    const spend = parseFloat(row.json['SPENT']) || 0;
    totalRevenue += rev;
    totalSpend += spend;
    entries.push({
      date: row.json['DATE'],
      name: row.json['NAME'],
      revenue: rev,
      spend: spend
    });
  }

  const profit = totalRevenue - totalSpend;
  const roi = totalSpend > 0
    ? (((totalRevenue - totalSpend) / totalSpend) * 100).toFixed(2)
    : 'N/A (no spend recorded)';

  return {
    totalRevenue: totalRevenue.toFixed(2),
    totalSpend: totalSpend.toFixed(2),
    totalProfit: profit.toFixed(2),
    roi,
    rowCount: rows.length,
    entries
  };
};

const thisWeekMetrics = calcMetrics(thisWeekRows);
const lastWeekMetrics = calcMetrics(lastWeekRows);

// Week-over-week revenue delta
const revDelta = (parseFloat(thisWeekMetrics.totalRevenue) - parseFloat(lastWeekMetrics.totalRevenue)).toFixed(2);
const revDeltaPct = parseFloat(lastWeekMetrics.totalRevenue) > 0
  ? (((parseFloat(thisWeekMetrics.totalRevenue) - parseFloat(lastWeekMetrics.totalRevenue)) / parseFloat(lastWeekMetrics.totalRevenue)) * 100).toFixed(2)
  : 'N/A';

return [{
  json: {
    thisWeek: {
      dateRange: `${thisWeekStart.toISOString().split('T')[0]} to ${now.toISOString().split('T')[0]}`,
      ...thisWeekMetrics
    },
    lastWeek: {
      dateRange: `${lastWeekStart.toISOString().split('T')[0]} to ${lastWeekEnd.toISOString().split('T')[0]}`,
      ...lastWeekMetrics
    },
    weekOverWeek: {
      revenueDelta: revDelta,
      revenueDeltaPct: `${revDeltaPct}%`
    }
  }
}];

const lastWeek = $input.first().json.lastWeek;
const thisWeek = $input.first().json.thisWeek;

const chartConfig = {
  type: "bar",
  data: {
    labels: ["Last Week", "This Week"],
    datasets: [
      {
        label: "Revenue",
        data: [parseFloat(lastWeek.totalRevenue), parseFloat(thisWeek.totalRevenue)],
        backgroundColor: "#34d399"
      },
      {
        label: "Spend",
        data: [parseFloat(lastWeek.totalSpend), parseFloat(thisWeek.totalSpend)],
        backgroundColor: "#f87171"
      },
      {
        label: "Profit",
        data: [parseFloat(lastWeek.totalProfit), parseFloat(thisWeek.totalProfit)],
        backgroundColor: "#a78bfa"
      }
    ]
  },
  options: {
    legend: { labels: { fontColor: "#aaaaaa" } },
    scales: {
      yAxes: [{ ticks: { fontColor: "#666666" } }],
      xAxes: [{ ticks: { fontColor: "#666666" } }]
    }
  }
};

const encoded = encodeURIComponent(JSON.stringify(chartConfig));
const chartUrl = `https://quickchart.io/chart?width=620&height=300&backgroundColor=%23111111&c=${encoded}`;

return [{ json: { chartUrl, ...($input.first().json) } }];

